type_pretty:
∀ (n r : ℕ),
  n > 1 →
    r > 0 →
      n.gcd r = 1 →
        let R := Polynomial (ZMod n);
        have X := Polynomial.X;
        have I := Ideal.span {X ^ r - 1};
        (Ideal.Quotient.mk I) ((X - 1) ^ n) = (Ideal.Quotient.mk I) (X ^ n - 1) →
          (Ideal.Quotient.mk I) ((X + 2) ^ n) = (Ideal.Quotient.mk I) (X ^ n + 2) → Nat.Prime n ∨ ↑n ^ 2 = 1
